export interface ClientOptions {
  space: string;
  token: string;
  /** When true the client also returns unpublished items. Unused today. */
  draft?: boolean;
}

export interface ContentItem {
  id: string;
  title: string;
  published: boolean;
}

type Listener = () => void;

/**
 * The content client every codeline vendors. Created once per app, at the site named in
 * `createClient` below. Both `draft` and `onContentChange` are supported and neither is used.
 */
export class ContentClient {
  private listeners: Listener[] = [];

  constructor(public readonly options: ClientOptions) {}

  async fetchItems(): Promise<ContentItem[]> {
    const all: ContentItem[] = [
      { id: 'a', title: 'Published item', published: true },
      { id: 'b', title: 'Unpublished item', published: false },
    ];
    return this.options.draft ? all : all.filter((i) => i.published);
  }

  /** Fires when content changes upstream. Nothing subscribes to it today. */
  onContentChange(fn: Listener): () => void {
    this.listeners.push(fn);
    return () => { this.listeners = this.listeners.filter((l) => l !== fn); };
  }

  _emit(): void { for (const l of this.listeners) l(); }
}

