import { ContentClient } from '../lib/content-client';
import { SPACE_ID, ACCESS_TOKEN } from '../constants/content';

/**
 * THE one place this codeline creates its content client.
 * Every fetch path below goes through this instance.
 */
export const client = new ContentClient({
  space: SPACE_ID,
  token: ACCESS_TOKEN,
  draft: false,
});

