import type { ContentItem } from '../lib/content-client';

export function renderList(items: ContentItem[]): string {
  if (items.length === 0) return '<p>Nothing to show.</p>';
  return '<ul>' + items.map((i) => `<li>${i.title}</li>`).join('') + '</ul>';
}

