import { client } from '../services/content';
import type { ContentItem } from '../lib/content-client';

/**
 * The single fetch path for this codeline. Callers re-invoke `load` to refresh.
 */
export function createContentSource() {
  let items: ContentItem[] = [];
  const load = async (): Promise<ContentItem[]> => {
    items = await client.fetchItems();
    return items;
  };
  const current = (): ContentItem[] => items;
  return { load, current };
}

