import { client } from '../services/content';
import type { ContentItem } from '../lib/content-client';

/**
 * App-wide content store. Unique to this codeline: every page reads from here rather than
 * fetching for itself, so a refresh has to be wired in ONCE, here.
 */
class ContentProvider {
  private cache: ContentItem[] = [];
  private loaded = false;

  async items(): Promise<ContentItem[]> {
    if (!this.loaded) {
      this.cache = await client.fetchItems();
      this.loaded = true;
    }
    return this.cache;
  }

  invalidate(): void { this.loaded = false; }
}

export const contentProvider = new ContentProvider();

